<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import MarketplaceLayout from '@/Layouts/MarketplaceLayout.vue';
import AppNotice from '@/Components/Product/AppNotice.vue';
const props = defineProps({ sent: Boolean, confirming: Boolean, valid: Boolean, maskedEmail: String, needsTerms: Boolean, retryAt: Number, googleEnabled: Boolean });
const remaining=ref(0);let timer;
onMounted(()=>{timer=setInterval(()=>{remaining.value=Math.max(0,Math.ceil(((props.retryAt||0)-Date.now())/1000));},1000);remaining.value=Math.max(0,Math.ceil(((props.retryAt||0)-Date.now())/1000));});
onBeforeUnmount(()=>clearInterval(timer));
const form = useForm({ email: '', accepted: false });
const submit = () => form.post(props.confirming ? '/marketplace/sign-in/confirm' : '/marketplace/sign-in', { preserveScroll: true });
</script>
<template><MarketplaceLayout><Head title="Your customer account | Clipperdesk Marketplace" /><main class="mp-container mp-narrow"><p class="mp-eyebrow">YOUR LITTLE CORNER OF CLIPPERDESK</p><h1 class="mp-title">Good to see you.</h1><p class="mp-lead">Your bookings, favourite salons and conversations.<br />All in one place.</p><section class="mp-card">
<template v-if="confirming"><h2>{{ valid ? 'Your account is one step away' : 'Let’s get you a fresh link' }}</h2><template v-if="valid"><p class="mp-muted">Continue as {{ maskedEmail }}. We’ll create your customer account if this is your first visit.</p><form @submit.prevent="submit"><label v-if="needsTerms" class="mp-check"><input v-model="form.accepted" type="checkbox" required /><span>I agree to the <Link href="/marketplace/terms">Marketplace terms</Link> and have read the <a href="/privacy-policy">Privacy notice</a>.</span></label><p v-if="form.errors.accepted || form.errors.email" class="mp-error" role="alert">{{ form.errors.accepted || form.errors.email }}</p><div class="mp-actions"><button class="mp-button" :disabled="form.processing">{{ form.processing ? 'Opening your account…' : 'Continue to my account' }}</button><Link class="mp-button secondary" href="/marketplace/sign-in">Use a different email</Link></div></form></template><template v-else><AppNotice title="This sign-in link has expired or was already used" description="Your bookings are still saved. Request a new link to open your account." /><div class="mp-actions"><Link class="mp-button" href="/marketplace/sign-in">Get a new sign-in link</Link></div></template></template>
<template v-else><h2>Log in or sign up</h2><a v-if="googleEnabled" href="/marketplace/auth/google" class="mp-google-button"><svg aria-hidden="true" viewBox="0 0 24 24" width="20" height="20"><path fill="#4285F4" d="M21.8 12.2c0-.7-.1-1.4-.2-2.1H12v4h5.5a4.7 4.7 0 0 1-2 3v2.5h3.3c1.9-1.8 3-4.3 3-7.4z"/><path fill="#34A853" d="M12 22c2.7 0 5-.9 6.8-2.4l-3.3-2.6c-.9.6-2.1 1-3.5 1-2.7 0-5-1.8-5.8-4.3H2.8v2.7A10 10 0 0 0 12 22z"/><path fill="#FBBC05" d="M6.2 13.7a6 6 0 0 1 0-3.4V7.6H2.8a10 10 0 0 0 0 8.8z"/><path fill="#EA4335" d="M12 6c1.5 0 2.8.5 3.8 1.5l2.9-2.8A9.7 9.7 0 0 0 12 2a10 10 0 0 0-9.2 5.6l3.4 2.7C7 7.8 9.3 6 12 6z"/></svg>Continue with Google</a><AppNotice v-if="form.errors.google || $page.props.errors?.google" tone="warning" title="Try email sign-in" :description="form.errors.google || $page.props.errors.google" /><div v-if="googleEnabled" class="mp-signin-divider"><span>or continue with email</span></div><AppNotice v-if="sent" title="Check your inbox" description="Your private sign-in link expires in 15 minutes. Check your spam folder too. You can request another after one minute." /><p class="mp-muted">Enter your email and we’ll send a private link. No password to remember.</p><form @submit.prevent="submit"><label class="mp-field"><span>Email address</span><input v-model="form.email" type="email" required autocomplete="email" maxlength="254" :aria-invalid="!!form.errors.email" aria-describedby="email-error" /></label><p v-if="form.errors.email" id="email-error" class="mp-error" role="alert">{{ form.errors.email }}</p><div class="mp-actions"><button class="mp-button" :disabled="form.processing || remaining>0">{{ remaining>0 ? `Request another link in ${remaining}s` : form.processing ? 'Sending your link…' : 'Email me a sign-in link' }}</button></div></form><p class="mp-muted" style="margin-top:24px">Looking after a salon? <a href="/login" style="text-decoration:underline">Log in to Clipperdesk Business</a>.</p></template>
</section><p class="mp-muted">You can still book without an account. <Link href="/marketplace" style="text-decoration:underline">Explore salons</Link>.</p></main></MarketplaceLayout></template>
